// ---------------------------------------------------------------------------
// Take the order from Store A and build a DRAFT ORDER for Store B (supplier).
// For each line item, find the matching Store B product:
//   1. by SKU   (best  — when both stores share SKUs)
//   2. by TITLE (brand/vendor stripped, e.g. 'Rolex Gold Watch' -> 'gold watch')
// Requires two n8n env vars for STORE B:
//   SHOPIFY_B_STORE = supplier-store.myshopify.com
//   SHOPIFY_B_TOKEN = shpat_...  (Admin API token, scopes: read_products, write_draft_orders)
// ---------------------------------------------------------------------------
const store = $env.SHOPIFY_B_STORE;
const token = $env.SHOPIFY_B_TOKEN;
const API = '2024-10';

const order = $input.first().json.body || $input.first().json;
const lineItems = order.line_items || [];
const cust = order.customer || {};
const ship = order.shipping_address || {};
const email = order.email || cust.email || '';

// Brands to strip when matching by title. Store A's line-item vendor is always
// stripped automatically; add any extra brand words you carry here.
const BRAND_STOPWORDS = ['rolex','gucci','nike','adidas','apple','samsung','original','genuine','brand'];

function cleanTitle(title, vendor) {
  let q = String(title || '').toLowerCase();
  if (vendor) q = q.split(String(vendor).toLowerCase()).join(' ');
  for (const w of BRAND_STOPWORDS) q = q.replace(new RegExp('\\b' + w + '\\b', 'gi'), ' ');
  return q.replace(/\s+/g, ' ').trim();
}

const gidToNumeric = (v) => (v == null ? null : String(v).split('/').pop());

const gql = async (query, variables) => {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://${store}/admin/api/${API}/graphql.json`,
    headers: { 'X-Shopify-Access-Token': token, 'Content-Type': 'application/json' },
    body: { query, variables },
    json: true,
  });
  return res && res.data;
};

const findBySku = async (sku) => {
  if (!sku) return null;
  const d = await gql('query($q:String!){productVariants(first:1,query:$q){edges{node{id sku product{title}}}}}', { q: `sku:${sku}` });
  const node = d && d.productVariants && d.productVariants.edges && d.productVariants.edges[0] && d.productVariants.edges[0].node;
  if (!node) return null;
  return { variant_id: Number(gidToNumeric(node.id)), matchedTitle: node.product.title, by: 'sku' };
};

const findByTitle = async (term) => {
  const d = await gql('query($q:String!){products(first:1,query:$q){edges{node{title variants(first:1){edges{node{id}}}}}}}', { q: term });
  const edge = d && d.products && d.products.edges && d.products.edges[0];
  const v = edge && edge.node && edge.node.variants && edge.node.variants.edges && edge.node.variants.edges[0] && edge.node.variants.edges[0].node;
  if (!v) return null;
  return { variant_id: Number(gidToNumeric(v.id)), matchedTitle: edge.node.title, by: 'title' };
};

const line_items = [];
const matches = [];
const unmatched = [];

for (const li of lineItems) {
  let found = await findBySku(li.sku);
  if (!found) {
    const term = cleanTitle(li.title, li.vendor);
    found = await findByTitle(term);
  }
  if (found) {
    line_items.push({ variant_id: found.variant_id, quantity: li.quantity || 1 });
    matches.push({ ordered: li.title, matched: found.matchedTitle, by: found.by });
  } else {
    unmatched.push({ title: li.title, sku: li.sku || null });
  }
}

const draft_order = {
  line_items,
  note: `Relayed from Store A order ${order.name || order.id || ''}`,
  tags: `order-relay,${order.name || ''}`,
  shipping_address: {
    first_name: ship.first_name || cust.first_name || 'Customer',
    last_name: ship.last_name || cust.last_name || '-',
    address1: ship.address1 || '',
    address2: ship.address2 || '',
    city: ship.city || '',
    province: ship.province || '',
    country: ship.country || 'Egypt',
    zip: ship.zip || '',
    phone: ship.phone || cust.phone || '',
  },
};
if (email) draft_order.email = email;

return [{
  json: {
    orderName: order.name || null,
    hasItems: line_items.length > 0,
    hasEmail: Boolean(email),
    email,
    matches,
    unmatched,
    body: { draft_order },
  },
}];
